-- Phase 2 schema: cricket teams, players, series, fixtures and points tables.
-- Same conventions as V1: uuid keys generated by the application, timestamptz in UTC,
-- application written timestamps, optimistic locking via version.
--
-- Deletion policy: teams, players and series are deactivated (active = false), never deleted,
-- because fixtures reference them. A fixture can be hidden (visible = false) or deleted.

CREATE TABLE cricket_team (
    id            uuid         NOT NULL,
    slug          varchar(200) NOT NULL,
    name          varchar(160) NOT NULL,
    short_name    varchar(24)  NOT NULL,
    category      varchar(24)  NOT NULL,
    country_code  varchar(8),
    flag_emoji    varchar(32),
    sport         varchar(32)  NOT NULL DEFAULT 'cricket',
    description   text,
    logo_url      varchar(2048),
    active        boolean      NOT NULL DEFAULT true,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_cricket_team PRIMARY KEY (id),
    CONSTRAINT uq_cricket_team_slug UNIQUE (slug),
    CONSTRAINT ck_cricket_team_category CHECK (category IN ('INTERNATIONAL', 'LEAGUE', 'DOMESTIC'))
);

CREATE TABLE cricket_player (
    id             uuid         NOT NULL,
    slug           varchar(200) NOT NULL,
    full_name      varchar(160) NOT NULL,
    team_id        uuid,
    country        varchar(80),
    role           varchar(80),
    batting_style  varchar(80),
    bowling_style  varchar(80),
    born_on        date,
    image_url      varchar(2048),
    description    text,
    active         boolean      NOT NULL DEFAULT true,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    updated_at     timestamptz  NOT NULL DEFAULT now(),
    version        bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_cricket_player PRIMARY KEY (id),
    CONSTRAINT uq_cricket_player_slug UNIQUE (slug),
    CONSTRAINT fk_cricket_player_team FOREIGN KEY (team_id)
        REFERENCES cricket_team (id) ON DELETE SET NULL
);

CREATE INDEX idx_cricket_player_team ON cricket_player (team_id);

CREATE TABLE cricket_tournament (
    id           uuid         NOT NULL,
    slug         varchar(200) NOT NULL,
    name         varchar(200) NOT NULL,
    short_name   varchar(60),
    description  text,
    format       varchar(24)  NOT NULL,
    category     varchar(24)  NOT NULL,
    season       varchar(40),
    host         varchar(160),
    dates_text   varchar(120),
    start_date   date,
    end_date     date,
    status       varchar(24)  NOT NULL,
    logo_url     varchar(2048),
    active       boolean      NOT NULL DEFAULT true,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    version      bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_cricket_tournament PRIMARY KEY (id),
    CONSTRAINT uq_cricket_tournament_slug UNIQUE (slug),
    CONSTRAINT ck_cricket_tournament_format
        CHECK (format IN ('TEST', 'ODI', 'T20I', 'T20', 'T10', 'THE_HUNDRED', 'OTHER')),
    CONSTRAINT ck_cricket_tournament_category CHECK (category IN ('INTERNATIONAL', 'LEAGUE', 'DOMESTIC')),
    CONSTRAINT ck_cricket_tournament_status CHECK (status IN ('UPCOMING', 'ONGOING', 'COMPLETED')),
    CONSTRAINT ck_cricket_tournament_dates CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);

CREATE TABLE cricket_tournament_team (
    tournament_id uuid NOT NULL,
    team_id       uuid NOT NULL,
    CONSTRAINT pk_cricket_tournament_team PRIMARY KEY (tournament_id, team_id),
    CONSTRAINT fk_cricket_tournament_team_tournament FOREIGN KEY (tournament_id)
        REFERENCES cricket_tournament (id) ON DELETE CASCADE,
    CONSTRAINT fk_cricket_tournament_team_team FOREIGN KEY (team_id)
        REFERENCES cricket_team (id) ON DELETE CASCADE
);

CREATE INDEX idx_cricket_tournament_team_team ON cricket_tournament_team (team_id);

CREATE TABLE cricket_match (
    id            uuid         NOT NULL,
    slug          varchar(200) NOT NULL,
    tournament_id uuid,
    team1_id      uuid         NOT NULL,
    team2_id      uuid         NOT NULL,
    format        varchar(24)  NOT NULL,
    category      varchar(24)  NOT NULL,
    venue         varchar(200),
    start_time    timestamptz  NOT NULL,
    status        varchar(24)  NOT NULL,
    match_number  varchar(60),
    team1_score   varchar(80),
    team2_score   varchar(80),
    note          varchar(300),
    result_text   varchar(300),
    visible       boolean      NOT NULL DEFAULT true,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT pk_cricket_match PRIMARY KEY (id),
    CONSTRAINT uq_cricket_match_slug UNIQUE (slug),
    CONSTRAINT ck_cricket_match_teams CHECK (team1_id <> team2_id),
    CONSTRAINT ck_cricket_match_format
        CHECK (format IN ('TEST', 'ODI', 'T20I', 'T20', 'T10', 'THE_HUNDRED', 'OTHER')),
    CONSTRAINT ck_cricket_match_category CHECK (category IN ('INTERNATIONAL', 'LEAGUE', 'DOMESTIC')),
    CONSTRAINT ck_cricket_match_status CHECK (status IN ('SCHEDULED', 'LIVE', 'COMPLETED', 'ABANDONED')),
    CONSTRAINT fk_cricket_match_tournament FOREIGN KEY (tournament_id)
        REFERENCES cricket_tournament (id) ON DELETE SET NULL,
    CONSTRAINT fk_cricket_match_team1 FOREIGN KEY (team1_id) REFERENCES cricket_team (id),
    CONSTRAINT fk_cricket_match_team2 FOREIGN KEY (team2_id) REFERENCES cricket_team (id)
);

CREATE INDEX idx_cricket_match_start_time ON cricket_match (start_time);
CREATE INDEX idx_cricket_match_status ON cricket_match (status);
CREATE INDEX idx_cricket_match_tournament ON cricket_match (tournament_id);
CREATE INDEX idx_cricket_match_team1 ON cricket_match (team1_id);
CREATE INDEX idx_cricket_match_team2 ON cricket_match (team2_id);

CREATE TABLE cricket_standing (
    id            uuid        NOT NULL,
    tournament_id uuid        NOT NULL,
    team_id       uuid        NOT NULL,
    position      integer     NOT NULL DEFAULT 0,
    played        integer     NOT NULL DEFAULT 0,
    won           integer     NOT NULL DEFAULT 0,
    lost          integer     NOT NULL DEFAULT 0,
    tied          integer     NOT NULL DEFAULT 0,
    no_result     integer     NOT NULL DEFAULT 0,
    points        integer     NOT NULL DEFAULT 0,
    nrr           varchar(24),
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    version       bigint      NOT NULL DEFAULT 0,
    CONSTRAINT pk_cricket_standing PRIMARY KEY (id),
    CONSTRAINT uq_cricket_standing_team UNIQUE (tournament_id, team_id),
    CONSTRAINT ck_cricket_standing_counts CHECK (
        played >= 0 AND won >= 0 AND lost >= 0 AND tied >= 0 AND no_result >= 0 AND points >= 0),
    CONSTRAINT fk_cricket_standing_tournament FOREIGN KEY (tournament_id)
        REFERENCES cricket_tournament (id) ON DELETE CASCADE,
    CONSTRAINT fk_cricket_standing_team FOREIGN KEY (team_id) REFERENCES cricket_team (id)
);

CREATE INDEX idx_cricket_standing_tournament ON cricket_standing (tournament_id, position);
